import time

class CircuitBreaker:
    def __init__(self, max_failures=3, cooldown=30, clock=None):
        self.max_failures = max_failures
        self.cooldown = cooldown
        self.clock = clock or time.time
        self.failures = 0
        self.opened_at = None

    def call(self, fn, fallback):
        if self.opened_at is not None and self.clock() - self.opened_at < self.cooldown:
            return fallback                      # open: don't touch the dependency
        try:
            result = fn()
        except Exception:
            self.failures += 1
            if self.opened_at is not None or self.failures >= self.max_failures:
                self.opened_at = self.clock()    # (re)open
            return fallback
        self.failures, self.opened_at = 0, None  # success closes it
        return result

def apply_events(events):
    seen, best, dupes = set(), {}, 0
    for e in events:
        if e["event_id"] in seen:
            dupes += 1
            continue
        seen.add(e["event_id"])
        key = (e["ts"], e["event_id"])
        cur = best.get(e["order_id"])
        if cur is None or key > cur[0]:
            best[e["order_id"]] = (key, e["status"])
    return {oid: status for oid, (_, status) in best.items()}, dupes

