class Flaky:
    def __init__(self, fails):
        self.fails, self.calls = fails, 0
    def __call__(self):
        self.calls += 1
        if self.calls <= self.fails:
            raise RuntimeError("timeout")
        return "ok"

def _run(fails, tries):
    waits = []
    f = Flaky(fails)
    try:
        r = call_with_retry(f, max_tries=tries, base=1.0, sleep=waits.append)
    except RuntimeError:
        r = "raised"
    return r, f.calls, waits

