import time

def call_with_retry(fn, max_tries=3, base=1.0, sleep=None):
    if sleep is None:
        sleep = time.sleep
    for attempt in range(max_tries):
        try:
            return fn()
        except Exception:
            if attempt == max_tries - 1:
                raise
            sleep(base * 2 ** attempt)

def score(preds, golds, cats):
    norm = lambda s: s.strip().lower()
    hits, totals = {}, {}
    for p, g, c in zip(preds, golds, cats):
        ok = norm(p) == norm(g)
        hits[c] = hits.get(c, 0) + ok
        totals[c] = totals.get(c, 0) + 1
    n = sum(totals.values())
    out = {"overall": (sum(hits.values()) / n) if n else 0.0}
    for c in totals:
        out[c] = hits[c] / totals[c]
    return out

def trim_history(messages, budget):
    cost = lambda m: len(m[1].split())
    head, rest, used = [], messages, 0
    if messages and messages[0][0] == "system":
        head, rest, used = [messages[0]], messages[1:], cost(messages[0])
    tail = []
    for m in reversed(rest):
        if used + cost(m) > budget:
            break
        tail.append(m)
        used += cost(m)
    return head + tail[::-1]

